ALTER POLICY pm_storage_insert ON storage.objects WITH CHECK(bucket_id='projects-attachments' AND (storage.foldername(objects.name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.pm_tasks t WHERE t.id::text=(storage.foldername(objects.name))[2] AND public.pm_can_edit(t.project_id))); ALTER POLICY pm_storage_read ON storage.objects USING(bucket_id='projects-attachments' AND EXISTS(SELECT 1 FROM public.pm_tasks t WHERE t.id::text=(storage.foldername(objects.name))[2] AND public.pm_can_edit(t.project_id)));